// Pure domain: validation and rules. No I/O.

export const MAX_TITLE = 200;
export const MAX_BODY = 100_000;
export const MAX_REQUEST_BYTES = 2 * 1024 * 1024;

export interface FieldError { field: string; message: string }
export type Parsed<T> = { ok: true; value: T } | { ok: false; errors: FieldError[] };

export const cpLength = (s: string): number => [...s].length;

const READ_ONLY = ["id", "teamId", "authorId", "version", "createdAt", "updatedAt", "deletedAt"];
const WRITABLE = ["title", "body"];

function validate(
  input: unknown,
  requireTitle: boolean,
): Parsed<{ title?: string; body?: string }> {
  if (input === null || typeof input !== "object" || Array.isArray(input)) {
    return { ok: false, errors: [{ field: "(body)", message: "must be a JSON object" }] };
  }
  const obj = input as Record<string, unknown>;
  const errors: FieldError[] = [];
  for (const k of Object.keys(obj)) {
    if (READ_ONLY.includes(k)) errors.push({ field: k, message: "is read-only" });
    else if (!WRITABLE.includes(k)) errors.push({ field: k, message: "unknown field" });
  }
  const out: { title?: string; body?: string } = {};
  if ("title" in obj) {
    if (typeof obj.title !== "string") errors.push({ field: "title", message: "must be a string" });
    else {
      const t = obj.title.trim();
      const n = cpLength(t);
      if (n < 1 || n > MAX_TITLE) errors.push({ field: "title", message: `must be 1-${MAX_TITLE} characters after trimming` });
      else out.title = t;
    }
  } else if (requireTitle) errors.push({ field: "title", message: "is required" });
  if ("body" in obj) {
    if (typeof obj.body !== "string") errors.push({ field: "body", message: "must be a string" });
    else if (cpLength(obj.body) > MAX_BODY) errors.push({ field: "body", message: `must be at most ${MAX_BODY} characters` });
    else out.body = obj.body;
  }
  if (!requireTitle && errors.length === 0 && Object.keys(obj).length === 0) {
    errors.push({ field: "(body)", message: "must contain at least one field" });
  }
  return errors.length ? { ok: false, errors } : { ok: true, value: out };
}

export const parseCreate = (input: unknown): Parsed<{ title: string; body: string }> => {
  const r = validate(input, true);
  if (!r.ok) return r;
  return { ok: true, value: { title: r.value.title!, body: r.value.body ?? "" } };
};

export const parsePatch = (input: unknown) => validate(input, false);

export const etagFor = (version: number): string => `"${version}"`;

export type Precondition =
  | { kind: "missing" }
  | { kind: "version"; matches: (v: number) => boolean };

/** Interpret an If-Match header. Missing or `*` -> "missing" (428). */
export function parseIfMatch(header: string | null): Precondition {
  if (header === null) return { kind: "missing" };
  const h = header.trim();
  if (h === "" || h === "*") return { kind: "missing" };
  const tags = h.split(",").map((s) => s.trim());
  return { kind: "version", matches: (v) => tags.includes(etagFor(v)) };
}

export const isJsonContentType = (ct: string | null): boolean =>
  (ct ?? "").split(";")[0].trim().toLowerCase() === "application/json";

export const isoNow = (): string => new Date().toISOString();
import {
  etagFor, isJsonContentType, isoNow, MAX_REQUEST_BYTES, parseCreate, parseIfMatch, parsePatch,
  type FieldError,
} from "./domain.ts";
import type { Note, Store, User } from "./store.ts";

const PROBLEM = "application/problem+json";

function problem(status: number, title: string, extra: Record<string, unknown> = {}, headers: HeadersInit = {}): Response {
  return new Response(
    JSON.stringify({ type: `https://teamnotes.example/problems/${status}`, title, status, ...extra }),
    { status, headers: { "content-type": PROBLEM, ...headers } },
  );
}
// One fixed body: hidden, missing, malformed and unknown routes are byte-identical.
const notFound = () => problem(404, "Not Found");
const json = (status: number, body: unknown, headers: HeadersInit = {}) =>
  new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json", ...headers } });
const noteResponse = (status: number, n: Note, headers: HeadersInit = {}) =>
  json(status, n, { etag: etagFor(n.version), ...headers });

type Body = { ok: true; value: unknown } | { ok: false; res: Response };

/** Reads the body applying 415 -> 413 -> 400 in order. */
async function readJson(req: Request): Promise<Body> {
  const len = req.headers.get("content-length");
  const hasBody = req.body !== null && len !== "0";
  if (hasBody && !isJsonContentType(req.headers.get("content-type"))) {
    return { ok: false, res: problem(415, "Unsupported Media Type") };
  }
  const tooLarge = () => ({
    ok: false as const,
    res: problem(413, "Payload Too Large", {}, { connection: "close" }),
  });
  if (len !== null && Number(len) > MAX_REQUEST_BYTES) return tooLarge();
  const buf = new Uint8Array(MAX_REQUEST_BYTES);
  let total = 0;
  if (req.body) {
    const reader = req.body.getReader();
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      if (total + value.byteLength > MAX_REQUEST_BYTES) { reader.cancel().catch(() => {}); return tooLarge(); }
      buf.set(value, total);
      total += value.byteLength;
    }
  }
  try {
    return { ok: true, value: JSON.parse(new TextDecoder().decode(buf.subarray(0, total))) };
  } catch {
    return { ok: false, res: problem(400, "Malformed JSON") };
  }
}

const invalid = (errors: FieldError[]) => problem(422, "Validation Failed", { errors });

function authenticate(req: Request, store: Store): User | null {
  const m = /^Bearer +(\S+)$/i.exec(req.headers.get("authorization") ?? "");
  return m ? store.userByToken(m[1]) : null;
}

export function createHandler(store: Store): (req: Request) => Promise<Response> {
  return async (req) => {
    try {
      return await route(req, store);
    } catch (e) {
      console.error(e);
      return problem(500, "Internal Server Error");
    }
  };
}

async function route(req: Request, store: Store): Promise<Response> {
  const url = new URL(req.url);
  const path = url.pathname;
  const method = req.method;
  if (path === "/health" && method === "GET") return json(200, { status: "ok" });

  const user = authenticate(req, store);
  if (!user) return problem(401, "Unauthorized", {}, { "www-authenticate": "Bearer" });

  if (path === "/me" && method === "GET") {
    return json(200, { id: user.id, name: user.name, teams: store.teamsOf(user.id) });
  }
  if (path === "/teams" && method === "GET") return json(200, { items: store.teamsOf(user.id) });

  let m = /^\/teams\/([^/]+)\/notes$/.exec(path);
  if (m && (method === "GET" || method === "POST")) {
    const teamId = decodeURIComponent(m[1]);
    if (!store.isMember(teamId, user.id)) return notFound();
    if (method === "GET") {
      return json(200, { items: store.listNotes(teamId, url.searchParams.get("archived") === "true") });
    }
    const body = await readJson(req);
    if (!body.ok) return body.res;
    const parsed = parseCreate(body.value);
    if (!parsed.ok) return invalid(parsed.errors);
    const note = store.createNote(teamId, user.id, parsed.value.title, parsed.value.body, isoNow());
    return noteResponse(201, note, { location: `/notes/${note.id}` });
  }

  m = /^\/notes\/([^/]+)(\/restore)?$/.exec(path);
  if (m) {
    const id = decodeURIComponent(m[1]);
    const visible = (): Note | null => {
      const n = store.findNote(id);
      return n && store.isMember(n.teamId, user.id) ? n : null;
    };
    if (!m[2]) {
      if (method === "GET") {
        const n = visible();
        return !n || n.deletedAt ? notFound() : noteResponse(200, n);
      }
      if (method === "DELETE") {
        const n = visible();
        if (!n) return notFound();
        store.softDelete(n.id, isoNow());
        return new Response(null, { status: 204 });
      }
      if (method === "PATCH") return await patch(req, store, visible());
    } else if (method === "POST") {
      const n = visible();
      if (!n) return notFound();
      return noteResponse(200, n.deletedAt ? store.restore(n.id, isoNow())! : n);
    }
  }
  return notFound();
}

async function patch(req: Request, store: Store, note: Note | null): Promise<Response> {
  if (!note || note.deletedAt) return notFound();
  const body = await readJson(req);
  if (!body.ok) return body.res;
  const parsed = parsePatch(body.value);
  if (!parsed.ok) return invalid(parsed.errors);
  const pre = parseIfMatch(req.headers.get("if-match"));
  if (pre.kind === "missing") return problem(428, "Precondition Required");
  // Re-read after the async body read so the check sees current state.
  const current = store.findNote(note.id);
  if (!current || current.deletedAt) return notFound();
  const stale = () => problem(412, "Precondition Failed", {}, { etag: etagFor(current.version) });
  if (!pre.matches(current.version)) return stale();
  const updated = store.updateNote(current.id, current.version, parsed.value, isoNow());
  return updated ? noteResponse(200, updated) : stale();
}
import { DatabaseSync } from "node:sqlite";
import { createHash } from "node:crypto";

export interface Note {
  id: string; teamId: string; authorId: string; title: string; body: string;
  version: number; createdAt: string; updatedAt: string; deletedAt?: string;
}
export interface TeamRole { id: string; name: string; role: "owner" | "member" }
export interface User { id: string; name: string }

type Row = Record<string, string | number | null>;
const toNote = (r: Row): Note => {
  const n: Note = {
    id: r.id as string, teamId: r.team_id as string, authorId: r.author_id as string,
    title: r.title as string, body: r.body as string, version: r.version as number,
    createdAt: r.created_at as string, updatedAt: r.updated_at as string,
  };
  if (r.deleted_at !== null) n.deletedAt = r.deleted_at as string;
  return n;
};

export class Store {
  private db: DatabaseSync;
  constructor(path: string, schemaSql: string) {
    this.db = new DatabaseSync(path);
    this.db.exec(schemaSql);
  }

  userByToken(token: string): User | null {
    const hash = createHash("sha256").update(token).digest("hex");
    const r = this.db.prepare("SELECT id, name FROM users WHERE token_hash = ?").get(hash) as Row | undefined;
    return r ? { id: r.id as string, name: r.name as string } : null;
  }

  teamsOf(userId: string): TeamRole[] {
    return (this.db.prepare(
      `SELECT t.id, t.name, m.role FROM memberships m JOIN teams t ON t.id = m.team_id
       WHERE m.user_id = ? ORDER BY t.id`).all(userId) as Row[])
      .map((r) => ({ id: r.id as string, name: r.name as string, role: r.role as "owner" | "member" }));
  }

  isMember(teamId: string, userId: string): boolean {
    return !!this.db.prepare("SELECT 1 FROM memberships WHERE team_id = ? AND user_id = ?").get(teamId, userId);
  }

  listNotes(teamId: string, archived: boolean): Note[] {
    const cond = archived ? "deleted_at IS NOT NULL" : "deleted_at IS NULL";
    return (this.db.prepare(`SELECT * FROM notes WHERE team_id = ? AND ${cond} ORDER BY seq DESC`).all(teamId) as Row[]).map(toNote);
  }

  /** Note by id regardless of deletion state. */
  findNote(id: string): Note | null {
    const r = this.db.prepare("SELECT * FROM notes WHERE id = ?").get(id) as Row | undefined;
    return r ? toNote(r) : null;
  }

  createNote(teamId: string, authorId: string, title: string, body: string, now: string): Note {
    const id = crypto.randomUUID();
    this.db.prepare(
      `INSERT INTO notes (id, team_id, author_id, title, body, version, created_at, updated_at)
       VALUES (?, ?, ?, ?, ?, 1, ?, ?)`).run(id, teamId, authorId, title, body, now, now);
    return this.findNote(id)!;
  }

  /** Compare-and-set update of a live note. Returns null if the version no longer matches. */
  updateNote(id: string, expected: number, fields: { title?: string; body?: string }, now: string): Note | null {
    const r = this.db.prepare(
      `UPDATE notes SET title = COALESCE(?, title), body = COALESCE(?, body),
         version = version + 1, updated_at = ?
       WHERE id = ? AND version = ? AND deleted_at IS NULL`)
      .run(fields.title ?? null, fields.body ?? null, now, id, expected);
    return r.changes === 1 ? this.findNote(id) : null;
  }

  /** Idempotent soft delete: keeps the original deletedAt if already deleted. */
  softDelete(id: string, now: string): void {
    this.db.prepare("UPDATE notes SET deleted_at = ? WHERE id = ? AND deleted_at IS NULL").run(now, id);
  }

  /** Restores a deleted note (version+1); a live note is returned untouched. */
  restore(id: string, now: string): Note | null {
    this.db.prepare(
      `UPDATE notes SET deleted_at = NULL, version = version + 1, updated_at = ?
       WHERE id = ? AND deleted_at IS NOT NULL`).run(now, id);
    return this.findNote(id);
  }
}
import { Store } from "./store.ts";
import { createHandler } from "./http.ts";

export function createStore(dbPath = ":memory:"): Store {
  const schema = Deno.readTextFileSync(new URL("../../spec/schema.sql", import.meta.url));
  return new Store(dbPath, schema);
}

if (import.meta.main) {
  const port = Number(Deno.env.get("PORT") ?? "3002");
  const store = createStore(Deno.env.get("DB_PATH") ?? ":memory:");
  Deno.serve({ port }, createHandler(store));
}
import { assert, assertEquals } from "jsr:@std/assert@1";
import { cpLength, parseCreate, parseIfMatch, parsePatch } from "./domain.ts";
import { createStore } from "./main.ts";
import { createHandler } from "./http.ts";

// ---- domain (pure) ----
Deno.test("title is trimmed and counted in code points", () => {
  const ok = parseCreate({ title: "  hi  " });
  assert(ok.ok && ok.value.title === "hi" && ok.value.body === "");
  assert(parseCreate({ title: "😀".repeat(200) }).ok);
  assert(!parseCreate({ title: "😀".repeat(201) }).ok);
  assertEquals(cpLength("😀"), 1);
});

Deno.test("create rejects bad shapes with field names", () => {
  for (const bad of [null, [1], "x", {}, { title: 4 }, { title: "t", foo: 1 }, { title: "t", version: 2 }]) {
    const r = parseCreate(bad);
    assert(!r.ok && r.errors.length > 0, JSON.stringify(bad));
  }
  const r = parsePatch({ authorId: "carol" });
  assert(!r.ok && r.errors[0].field === "authorId");
  assert(!parsePatch({}).ok);
});

Deno.test("If-Match: missing and * are 'missing'; quoted version matches", () => {
  assertEquals(parseIfMatch(null).kind, "missing");
  assertEquals(parseIfMatch("*").kind, "missing");
  const p = parseIfMatch('"3"');
  assert(p.kind === "version" && p.matches(3) && !p.matches(2));
});

// ---- HTTP through the handler, no socket ----
const call = (h: (r: Request) => Promise<Response>, method: string, path: string, who: string | null, body?: unknown, headers: Record<string, string> = {}) =>
  h(new Request("http://x" + path, {
    method,
    headers: { ...(who ? { authorization: `Bearer tok_${who}` } : {}), ...(body !== undefined ? { "content-type": "application/json" } : {}), ...headers },
    body: body === undefined ? undefined : JSON.stringify(body),
  }));

Deno.test("note lifecycle: ETag, 428, 412, soft delete, restore, trash", async () => {
  const h = createHandler(createStore());
  const created = await call(h, "POST", "/teams/team-red/notes", "alice", { title: "a", body: "b" });
  assertEquals(created.status, 201);
  assertEquals(created.headers.get("etag"), '"1"');
  const n = await created.json();
  assertEquals((await call(h, "PATCH", `/notes/${n.id}`, "bob", { title: "c" })).status, 428);
  assertEquals((await call(h, "PATCH", `/notes/${n.id}`, "bob", { title: "c" }, { "if-match": "*" })).status, 428);
  const p = await call(h, "PATCH", `/notes/${n.id}`, "bob", { title: "c" }, { "if-match": '"1"' });
  assertEquals(p.headers.get("etag"), '"2"');
  assertEquals((await call(h, "PATCH", `/notes/${n.id}`, "alice", { title: "d" }, { "if-match": '"1"' })).status, 412);
  assertEquals((await call(h, "DELETE", `/notes/${n.id}`, "alice")).status, 204);
  assertEquals((await call(h, "DELETE", `/notes/${n.id}`, "alice")).status, 204);
  assertEquals((await call(h, "GET", `/notes/${n.id}`, "alice")).status, 404);
  const trash = await (await call(h, "GET", "/teams/team-red/notes?archived=true", "bob")).json();
  assertEquals(trash.items.length, 1);
  assert(trash.items[0].deletedAt);
  assertEquals((await call(h, "POST", `/notes/${n.id}/restore`, "carol")).status, 404);
  const r = await (await call(h, "POST", `/notes/${n.id}/restore`, "bob")).json();
  assertEquals([r.version, r.title, r.deletedAt], [3, "c", undefined]);
});

Deno.test("error precedence and identical 404s", async () => {
  const h = createHandler(createStore());
  const n = await (await call(h, "POST", "/teams/team-red/notes", "alice", { title: "s" })).json();
  const raw = (who: string | null, ct: string, body: string) =>
    h(new Request(`http://x/notes/${n.id}`, { method: "PATCH", headers: { ...(who ? { authorization: `Bearer tok_${who}` } : {}), "content-type": ct }, body }));
  assertEquals((await raw(null, "text/plain", "{")).status, 401);
  assertEquals((await raw("carol", "text/plain", "{")).status, 404);
  assertEquals((await raw("bob", "text/plain", "{")).status, 415);
  assertEquals((await raw("bob", "application/json", "{")).status, 400);
  const bodies = await Promise.all([n.id, crypto.randomUUID(), "not-a-uuid"].map(async (id) =>
    await (await call(h, "GET", `/notes/${id}`, "carol")).text()));
  assert(bodies.every((b) => b === bodies[0]));
});
